          {
            "snippet": "Constant fatigue: Feeling exhausted or low on energy even after a full night of sleep."
          },
          {
            "snippet": "Bone and back pain: A dull, deep ache in the lower back, ribs, pelvis, or legs due to poor calcium absorption."
          },
          {
            "snippet": "Muscle weakness and aches: Struggling with everyday physical tasks, muscle cramps, or slow recovery after workouts."
          },
          {
            "snippet": "Frequent sickness: Catching colds or other infections more easily because the immune system is weakened."
          },
          {
            "snippet": "Hair thinning: Experiencing unexplained hair shedding or hair loss."
          }
